const HEAD = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>fixture</title></head><body>";
const TAIL = "</body></html>";
const REC = "function rec(k,t){fetch('/_rec?k='+k+'&t='+encodeURIComponent(t))}function $(i){return document.getElementById(i)}";
const COMP = "<div role=\"main\"><h1>Home</h1><div role=\"button\" tabindex=\"0\" id=\"open\" aria-label=\"What's on your mind, Tester?\">What's on your mind, Tester?</div><div role=\"dialog\" id=\"dlg\" hidden><div role=\"textbox\" contenteditable=\"true\" id=\"box\" aria-label=\"What's on your mind?\"></div><div role=\"button\" tabindex=\"0\" id=\"aud\" aria-label=\"Audience\">Audience</div><div id=\"audm\" hidden><div role=\"option\" tabindex=\"0\" aria-label=\"Public\">Public</div><div role=\"option\" tabindex=\"0\" aria-label=\"Friends\">Friends</div></div><div role=\"button\" tabindex=\"0\" id=\"polb\" aria-label=\"Poll\">Poll</div><div role=\"textbox\" contenteditable=\"true\" id=\"po1\" aria-label=\"Option 1\"></div><div role=\"textbox\" contenteditable=\"true\" id=\"po2\" aria-label=\"Option 2\"></div><input type=\"file\" id=\"ph\" aria-label=\"Upload\"><div role=\"button\" tabindex=\"0\" id=\"pub\" aria-label=\"Post\">Post</div></div><div id=\"feed\"></div></div>";
const COMPJS = "$('open').onclick=function(){$('dlg').hidden=false;$('box').focus()};$('aud').onclick=function(){$('audm').hidden=false};document.querySelectorAll('#audm [role=option]').forEach(function(o){o.onclick=function(){rec('aud',o.getAttribute('aria-label'));$('audm').hidden=true}});$('ph').onchange=function(){rec('photo',this.files.length)};$('pub').onclick=function(){var t=$('box').innerText.trim();if(!t)return;rec('post',t);var o1=$('po1').innerText.trim(),o2=$('po2').innerText.trim();if(o1||o2)rec('poll',o1+'|'+o2);var a=document.createElement('div');a.setAttribute('role','article');a.textContent=t;$('feed').appendChild(a);$('dlg').hidden=true};";
pub const HOME = HEAD ++ COMP ++ "<script>" ++ REC ++ COMPJS ++ "</script>" ++ TAIL;
pub const GROUP = HEAD ++ COMP ++ "<div role=\"button\" tabindex=\"0\" id=\"join\" aria-label=\"Join group\">Join group</div><script>" ++ REC ++ COMPJS ++ "$('join').onclick=function(){rec('join','77');$('join').textContent='Joined'};</script>" ++ TAIL;
pub const PROFILE = HEAD ++ "<h1>Ann Lee</h1><div role=\"button\" tabindex=\"0\" id=\"add\" aria-label=\"Add friend\">Add friend</div><script>" ++ REC ++ "$('add').onclick=function(){rec('friend','9');$('add').textContent='Request sent'};</script>" ++ TAIL;
pub const DMSG = HEAD ++ "<h1>Chat</h1><div role=\"textbox\" contenteditable=\"true\" id=\"m\" aria-label=\"Message\"></div><input type=\"file\" id=\"mf\" aria-label=\"Attach\"><div id=\"log\"></div><script>" ++ REC ++ "$('mf').onchange=function(){rec('mfile',this.files.length)};$('m').addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();var t=$('m').innerText.trim();var n=$('mf').files.length;if(!t&&!n)return;rec('dm',t);$('log').textContent+=t;$('m').innerText=''}});</script>" ++ TAIL;
const CMTJS = "document.querySelectorAll('.rb').forEach(function(b){b.onclick=function(){var bx=b.parentNode.querySelector('.rbox');bx.hidden=false;bx.querySelector('.rt').focus()}});document.querySelectorAll('.rt').forEach(function(r){r.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();var t=r.innerText.trim();if(!t)return;rec('reply',t);r.parentNode.hidden=true}})});$('mk').onclick=function(){rec('notimark','all')};";
pub const NOTI = HEAD ++ "<h1>Notifications</h1><div role=\"button\" tabindex=\"0\" id=\"mk\" aria-label=\"Mark all as read\">Mark all as read</div><div role=\"article\" aria-label=\"Comment by Ann\"><span class=\"t\">Is this still available?</span><div role=\"button\" tabindex=\"0\" class=\"rb\" aria-label=\"Reply\">Reply</div><div class=\"rbox\" hidden><div role=\"textbox\" contenteditable=\"true\" class=\"rt\" aria-label=\"Write a reply\"></div></div></div><div role=\"article\" aria-label=\"Comment by Bob\"><span class=\"t\">How much for the desk?</span><div role=\"button\" tabindex=\"0\" class=\"rb\" aria-label=\"Reply\">Reply</div><div class=\"rbox\" hidden><div role=\"textbox\" contenteditable=\"true\" class=\"rt\" aria-label=\"Write a reply\"></div></div></div><script>" ++ REC ++ CMTJS ++ "</script>" ++ TAIL;
pub const MCRE = HEAD ++ "<h1>New listing</h1><input type=\"text\" id=\"ti\" aria-label=\"Title\"><input type=\"text\" id=\"pr\" aria-label=\"Price\"><textarea id=\"de\" aria-label=\"Description\"></textarea><input type=\"file\" id=\"ph\"><div role=\"button\" tabindex=\"0\" id=\"go\" aria-label=\"Publish\">Publish</div><script>" ++ REC ++ "$('go').onclick=function(){rec('list',$('ti').value+'|'+$('pr').value+'|'+$('de').value+'|'+$('ph').files.length);document.body.setAttribute('data-listing-id','L1001');var h=document.createElement('h2');h.textContent='Listing published';document.body.appendChild(h)};</script>" ++ TAIL;
