rec('sold',t);a.querySelector('h2').textContent=t+' (sold)'};a.querySelectorAll('[data-k]').forEach(function(b){b.onclick=function(){window.__t=t;rec(b.getAttribute('data-k'),t)}})});document.querySelectorAll('[data-p]').forEach(function(b){b.onclick=function(){rec('pg',b.getAttribute('aria-label'))}});</script>" ++ TAIL;
